-- Generated by matugen (PurcleShell). Source in hyprland.conf:
--   source = ~/.config/hypr/purcleshell-colors.conf

general {
    col.active_border = rgba({{colors.primary.default.hex_stripped}}ee)
    col.inactive_border = rgba({{colors.outline.default.hex_stripped}}aa)
}

group {
    col.border_active = rgba({{colors.primary.default.hex_stripped}}ee)
    col.border_inactive = rgba({{colors.outline.default.hex_stripped}}aa)
    col.border_locked_active = rgba({{colors.error.default.hex_stripped}}ee)
    col.border_locked_inactive = rgba({{colors.outline.default.hex_stripped}}aa)

    groupbar {
        col.active = rgba({{colors.primary.default.hex_stripped}}ee)
        col.inactive = rgba({{colors.outline.default.hex_stripped}}aa)
        col.locked_active = rgba({{colors.error.default.hex_stripped}}ee)
        col.locked_inactive = rgba({{colors.outline.default.hex_stripped}}aa)
    }
}
